import React, { useState, useEffect } from 'react';
import { Container, Typography, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Button, Chip } from '@mui/material';
import { useAuth } from '../context/AuthContext';
import axios from 'axios';

const Applications = () => {
  const { currentUser } = useAuth();
  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (currentUser?.role === 'student') {
      fetchStudentApplications();
    } else if (currentUser?.role === 'institution') {
      fetchInstitutionApplications();
    }
  }, [currentUser]);

  const fetchStudentApplications = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/students/applications');
      setApplications(response.data.applications);
    } catch (error) {
      console.error('Error fetching applications:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchInstitutionApplications = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/applications/institution');
      setApplications(response.data.applications);
    } catch (error) {
      console.error('Error fetching applications:', error);
    } finally {
      setLoading(false);
    }
  };

  const updateApplicationStatus = async (applicationId, status) => {
    try {
      await axios.put(`http://localhost:5000/api/applications/${applicationId}/status`, { status });
      // Refresh applications
      if (currentUser?.role === 'institution') {
        fetchInstitutionApplications();
      }
    } catch (error) {
      console.error('Error updating application:', error);
    }
  };

  if (!currentUser) {
    return (
      <Container>
        <Typography>Please log in to view applications</Typography>
      </Container>
    );
  }

  if (loading) {
    return (
      <Container>
        <Typography>Loading applications...</Typography>
      </Container>
    );
  }

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        {currentUser.role === 'student' ? 'My Applications' : 'Student Applications'}
      </Typography>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              {currentUser.role === 'institution' && <TableCell>Student</TableCell>}
              <TableCell>Course</TableCell>
              <TableCell>Institution</TableCell>
              <TableCell>Status</TableCell>
              <TableCell>Applied Date</TableCell>
              {currentUser.role === 'institution' && <TableCell>Actions</TableCell>}
            </TableRow>
          </TableHead>
          <TableBody>
            {applications.map((application) => (
              <TableRow key={application.id}>
                {currentUser.role === 'institution' && (
                  <TableCell>
                    {application.student?.personalInfo?.firstName} {application.student?.personalInfo?.lastName}
                  </TableCell>
                )}
                <TableCell>{application.course?.name}</TableCell>
                <TableCell>{application.institution?.name}</TableCell>
                <TableCell>
                  <Chip 
                    label={application.status} 
                    color={
                      application.status === 'admitted' ? 'success' :
                      application.status === 'rejected' ? 'error' : 'default'
                    }
                  />
                </TableCell>
                <TableCell>
                  {new Date(application.appliedAt).toLocaleDateString()}
                </TableCell>
                {currentUser.role === 'institution' && (
                  <TableCell>
                    <Button
                      size="small"
                      onClick={() => updateApplicationStatus(application.id, 'admitted')}
                      disabled={application.status === 'admitted'}
                    >
                      Admit
                    </Button>
                    <Button
                      size="small"
                      color="error"
                      onClick={() => updateApplicationStatus(application.id, 'rejected')}
                      disabled={application.status === 'rejected'}
                    >
                      Reject
                    </Button>
                  </TableCell>
                )}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {applications.length === 0 && (
        <Typography sx={{ mt: 2 }}>No applications found.</Typography>
      )}
    </Container>
  );
};

export default Applications;
